/* 界面多语言（zh / en）的词表与切换。
 *
 * 口径（人已点头的那一条改了）：界面文字全翻，运行日志也要跟着切。日志的切法不是去改落盘的那句话——
 * 条目仍带中文原文 message（历史记录、归档文件与 59 套自检断言的对象），另带一组可选的 k/kv「键 + 参数」，
 * 英文界面按 k 现拼一句显示，没带键的条目、旧条目、以及词表里查不到的，一律显示 message。
 * 后端因此从不读 ui_language：同一个日志文件，中文界面看中文，英文界面看英文，字节不变。
 *
 * 两类键的取值写法不一样，混了就会有一句前缀跑丢（由 tests/i18n_test.py 的 H 组钉住）：
 *   log.*  —— 后端自己写的行：zh 的值就是那句 message，**含**「[界面] 」前缀（前缀由后端拼进 message）。
 *   ui.*   —— 前端埋点走 /api/ui_event 的行：zh 的值**不含**前缀（前缀由后端加），en 的值自己带「[UI] 」。
 * zh 的词表值必须与改前模板里硬编码的那句一字不差，否则中文用户看到的界面就被我改动了。
 * 键的完整性由 tests/i18n_test.py 盯：模板里用到的每个键都要在词表里、zh 与 en 的键集合要一致、
 * 同一个键两边的 {n} 占位符要对得上 —— 不靠人记。
 */
