      'settings.credit.catCatch': 'GPL-3.0 resource-sniffing extension; this tool is the receiving end of its send-data action and imports its regex rules, talking only to the published config format - no code copied',
      'settings.credit.gd4b': 'A sibling implementation of a browser sniffing extension',
      'settings.credit.spotdl': 'Idea reference for the scoring gate that decides whether two tracks are the same (title, artist and duration each scored, then merged) - no code copied',
      'settings.credit.emby': 'Idea reference for reading a music library folder by folder (album / year / number - title) - no code copied',
      'settings.credit.jellyfin': 'Same as above: the order of {track} {disc} {year} {date} in the naming template follows how that player reads its library - no code copied',
      'settings.credit.goMusicDl': 'Idea reference for matching tracks by name across platforms and turning a playlist into links (an AGPL project - no code copied)',
      'settings.credit.simpleSqMusicPlus': 'Idea reference for chasing new releases in a playlist and keeping your own favourite lists - no code copied',
      'settings.credit.flacdownloaderCom': 'Where the Qobuz / Tidal lossless reference metadata (title, ISRC, whether lossless) comes from',
      'settings.credit.qbittorrentEnhancedEdition': 'GPL-3.0; the auto-updating trackers, the seeding and the rate limits on the magnet / torrent page were designed after its product shape. No code was copied at all, and the tracker list is not hardcoded either - it is fetched from a URL at run time',
      'settings.credit.creditTrackers': 'Tracker list sources',
