      'auth.minutesWord': 'minutes',
      'auth.rememberHint': '"Remember this device" is the tick in the login window: its maximum lifetime takes the value above, and without it the session is the idle {h} hours tier. The signing key used for login (SECRET_KEY) is generated the first time it is needed and written into config.json, so restarting the program does not make browsers sign in again. Locks and failure counts live in login_state.json and survive a restart, so a brute-forcer never gets a fresh round for free.',
      'auth.machineTokenLead': 'Machine token (the second gate for automated calls)',
      'auth.hideBtn': 'Hide',
      'auth.showBtn': 'Show',
      'auth.copyBtn': 'Copy',
      'auth.rotateBtn': 'Reset',
      'auth.tokenHintA': 'For scripts that have to cross hosts or a reverse proxy: put this string into the',
      'auth.tokenHintB': 'request header to pass the data endpoints, but it cannot do actions such as changing the password or flipping switches (even "turn protection off" is blocked with it). This string is only generated when you press "Reset" - reloading the interface writes nothing to disk. The MCP bridge only connects to 127.0.0.1, so by the rule above it never needs the gate; it reads the environment variable',
      'auth.tokenHintC': 'by itself, and with nothing set it reads this string straight out of the local config.json, so changing the binding later needs no change to the bridge. After a reset the old token dies immediately and the scripts have to be updated.',
