      'music.matchSrcHint': 'Whether you paste a whole playlist or a single link, entries like Spotify and NetEase Cloud that only bring back a title, artist and duration and no audio link depend on this list: at download time the link is fetched by title from these sources, and a row\'s "Switch" looks for the same song here too. Every source ticked here is searched and the candidates that passed the gate are compared, taking the highest score (on a tie the first ticked one wins) — hitting something in the first source does not skip the rest. The candidates are the same list as "Search sources" above and all of them can be picked; sources marked "slow to resolve" go through a third-party converter, take about ten seconds a track and often fail, so they aren\'t in any default. Only when nothing is chosen at all does it fall back to the default 5 sources, and the log says so',
